update ins_validate_rule
set
    update_time = #{validateRuleInfoModel.endTime},

    full_validate_status = #{validateRuleInfoModel.validateStatus}


    single_validate_status = #{validateRuleInfoModel.validateStatus}

where
    work_id = #{validateRuleInfoModel.workId}

mapper.select:
select

from ins_validate_rule
where
    regulation_id = #{validateRuleInfoModel.rulesId}
and single_or_full_type = #{validateRuleInfoModel.dataType}
order by create_time desc,update_time desc

select id, regulation_id, work_id, single_or_full_type, if(single_validate_status is null,'-1',single_validate_status) as single_validate_status, create_time, update_time, operator, if(full_validate_status is null ,'-1',full_validate_status) as full_validate_status from ins_validate_rule where regulation_id in
#{regulationId}
order by create_time desc,update_time desc
